<?php
/**
 * The page registry (data/pages.json, generated by tools/html-to-blocks.mjs
 * from the Next.js lib/seo.mjs PAGES): one record per URL with title,
 * description, share card, noindex, template and parent.
 *
 * @package eo-site
 */

defined( 'ABSPATH' ) || exit;

function eo_site_registry(): array {
	static $pages = null;
	if ( null === $pages ) {
		$raw   = file_get_contents( EO_SITE_DIR . 'data/pages.json' );
		$data  = json_decode( $raw, true );
		$pages = array();
		foreach ( $data['pages'] ?? array() as $p ) {
			$pages[ $p['path'] ] = $p;
		}
	}
	return $pages;
}

function eo_site_data(): array {
	static $data = null;
	if ( null === $data ) {
		$data = json_decode( file_get_contents( EO_SITE_DIR . 'data/site-data.json' ), true ) ?: array();
	}
	return $data;
}

/** The registry record for a page, by its WordPress path (/about/history/). */
function eo_site_record_for_post( $post ): ?array {
	$post = get_post( $post );
	if ( ! $post || 'page' !== $post->post_type ) {
		return null;
	}
	if ( (int) get_option( 'page_on_front' ) === (int) $post->ID ) {
		return eo_site_registry()['/'] ?? null;
	}
	$path = '/' . trim( (string) get_page_uri( $post ), '/' ) . '/';
	return eo_site_registry()[ $path ] ?? null;
}

/** The record for the current request, or null off the registry. */
function eo_site_current_record(): ?array {
	if ( is_front_page() && 'page' === get_option( 'show_on_front' ) ) {
		return eo_site_registry()['/'] ?? null;
	}
	if ( is_page() ) {
		return eo_site_record_for_post( get_queried_object_id() );
	}
	return null;
}

/** The registry title minus the site suffix: the breadcrumb and admin name. */
function eo_site_short_title( array $record ): string {
	$t = $record['title'];
	$t = preg_replace( '/\s+[—|]\s+Equality Ohio.*$/u', '', $t );
	if ( '/' === $record['path'] ) {
		return 'Home';
	}
	return $t;
}
